using System.Text.Json;
using System.Text.Json.Nodes;
using YamlDotNet.Serialization;
namespace Nuzul;

public static class Analysis
{
    public static JsonNode ParseApi(string content) { try { return JsonNode.Parse(content) ?? throw new Exception(); } catch (JsonException) { var obj = new DeserializerBuilder().Build().Deserialize<object>(content); var json = new SerializerBuilder().JsonCompatible().Build().Serialize(obj); return JsonNode.Parse(json) ?? throw new InvalidOperationException("Invalid OpenAPI"); } }
    public static void Extract(Project p, Source s)
    {
        if (s.Type.Contains("image", StringComparison.OrdinalIgnoreCase) || s.Type.Contains("screenshot", StringComparison.OrdinalIgnoreCase)) { p.Requirements.Add(new() { SourceId = s.Id, Reference = s.Name, Text = "Screenshot retained for static review. Endpoint behavior and business rules require documented evidence; no executable API inferred.", Status = "Unknown" }); return; }
        JsonNode? api = null; if (s.Type.Contains("openapi", StringComparison.OrdinalIgnoreCase) || s.Type.Contains("swagger", StringComparison.OrdinalIgnoreCase) || s.Content.TrimStart().StartsWith('{') || s.Content.Contains("openapi:")) { try { api = ParseApi(s.Content); } catch (Exception ex) { throw new InvalidOperationException("OpenAPI parse failed: " + ex.Message); } }
        if (api is JsonObject && api["paths"] is JsonObject paths) { foreach (var path in paths) if (path.Value is JsonObject ops) foreach (var op in ops) { if (op.Key is not ("get" or "post" or "put" or "patch" or "delete" or "head" or "options")) continue; var text = $"{op.Key.ToUpperInvariant()} {path.Key}: {op.Value?["summary"]} {op.Value?["description"]}. Responses: {op.Value?["responses"]?.ToJsonString()}. Request schema: {op.Value?["requestBody"]?.ToJsonString()}. Authentication: {op.Value?["security"] ?? api["security"]}."; p.Requirements.Add(new() { SourceId = s.Id, Reference = $"#/paths/{path.Key}/{op.Key}", Text = text, Status = "Verified" }); } if (api["components"] != null) p.Requirements.Add(new() { SourceId = s.Id, Reference = "#/components", Text = api["components"]!.ToJsonString(), Status = "Verified" }); return; }
        var lines = s.Content.Split('\n', StringSplitOptions.RemoveEmptyEntries).Where(x => !string.IsNullOrWhiteSpace(x)).Take(100); foreach (var line in lines) p.Requirements.Add(new() { SourceId = s.Id, Reference = $"{s.Name}:text", Text = line.Trim(), Status = "Inferred / Needs Review" });
    }
    public static List<object> Retrieve(Project p, string query) { var words = query.ToLowerInvariant().Split(' ', StringSplitOptions.RemoveEmptyEntries); return p.Requirements.Select(r => new { r, score = words.Count(w => r.Text.Contains(w, StringComparison.OrdinalIgnoreCase)) }).OrderByDescending(x => x.score).Take(8).Select(x => (object)new { sourceId = x.r.SourceId, sourceType = p.Sources.FirstOrDefault(s => s.Id == x.r.SourceId)?.Type, reference = x.r.Reference, excerpt = x.r.Text, requirementId = x.r.Id, score = x.score, testCaseIds = p.TestCases.Where(t => t.RequirementId == x.r.Id).Select(t => t.Id) }).ToList(); }
    public static void Design(Project p, bool lower)
    {
        foreach (var s in p.Sources)
        {
            JsonNode? api; try { api = ParseApi(s.Content); } catch { continue; }
            if (api is not JsonObject || api["paths"] is not JsonObject paths) continue; foreach (var path in paths) if (path.Value is JsonObject ops) foreach (var op in ops)
            {
                var req = p.Requirements.FirstOrDefault(r => r.SourceId == s.Id && r.Reference == $"#/paths/{path.Key}/{op.Key}"); if (req == null) continue; var responses = op.Value?["responses"] as JsonObject; var status = responses?.Select(x => int.TryParse(x.Key, out var n) ? n : 0).FirstOrDefault(n => n >= 200 && n < 300) ?? 0; var example = op.Value?["requestBody"]?["content"]?["application/json"]?["example"]?.ToJsonString() ?? ""; if (example.Length == 0 && op.Value?["requestBody"]?["content"]?["application/json"]?["examples"] is JsonObject examples) example = examples.FirstOrDefault().Value?["value"]?.ToJsonString() ?? "";
                Add(p, new() { Title = $"{op.Key.ToUpperInvariant()} {path.Key} — documented success", RequirementId = req.Id, Method = op.Key.ToUpperInvariant(), Path = path.Key, Body = example, InputData = example, ExpectedStatus = status == 0 ? null : status, ExpectedResult = status > 0 ? $"HTTP {status} per OpenAPI" : "Needs authoritative expected result", VerificationStatus = status > 0 ? "Verified" : "Needs Oracle / Needs Review", Steps = [$"Send {op.Key.ToUpperInvariant()} {path.Key}", "Compare response to documented status"], Preconditions = ["Target configured and reachable", "Review concrete path parameters and input data"], Assertions = status > 0 ? [new() { Kind = "status", Expected = status.ToString() }] : [] });
                if (op.Value?["x-test-cases"] is JsonArray cases) foreach (var c in cases) { if (c == null) continue; var priority = c["priority"]?.ToString() ?? "High"; if (!lower && priority is "Low" or "Medium") continue; var body = c["body"] is JsonValue cv && cv.TryGetValue<string>(out var cs) ? cs : c["body"]?.ToJsonString() ?? c["requestBody"]?.ToJsonString() ?? ""; var expected = int.TryParse(c["expectedStatus"]?.ToString(), out var st) ? st : 0; var sourceAssertions=c["assertions"]?.Deserialize<List<Assertion>>(Store.Json)??[];if(expected>0&&!sourceAssertions.Any(a=>a.Kind=="status"))sourceAssertions.Insert(0,new(){Kind="status",Expected=expected.ToString()}); Add(p, new() { Title = c["title"]?.ToString() ?? "Documented example", RequirementId = req.Id, Priority = priority, Method = op.Key.ToUpperInvariant(), Path = path.Key, Body = body, InputData = body, ExpectedStatus = expected == 0 ? null : expected, ExpectedResult = $"HTTP {expected}; {c["expectedResult"]}", VerificationStatus = expected > 0 ? "Verified" : "Needs Oracle / Needs Review", TestType = c["testType"]?.ToString() ?? "API validation", Preconditions = ["Explicit permission required for mutations"], Steps = [$"Send {op.Key.ToUpperInvariant()} {path.Key} with documented example", "Compare response with authoritative expected status"], Assertions = sourceAssertions }); }
            }
            if (api["x-test-cases"] is JsonArray rootCases) foreach (var c in rootCases) { if (c == null) continue; var method = c["method"]?.ToString() ?? "GET"; var pathValue = c["path"]?.ToString() ?? ""; var req = p.Requirements.FirstOrDefault(r => r.SourceId == s.Id && r.Reference == $"#/paths/{pathValue}/{method.ToLowerInvariant()}"); if (req == null) continue; var test = c.Deserialize<TestCase>(Store.Json)!; test.Id = Guid.NewGuid().ToString("N"); test.RequirementId = req.Id; test.VerificationStatus = "Verified"; test.Approved = false; test.InputData = test.Body; test.Steps = [$"Send {method} {pathValue} with the source example", "Verify authoritative assertions"]; if (test.ExpectedStatus.HasValue && !test.Assertions.Any(a => a.Kind == "status")) test.Assertions.Insert(0, new() { Kind = "status", Expected = test.ExpectedStatus.Value.ToString() }); Add(p, test); }
        }
        foreach (var r in p.Requirements.Where(r => !p.TestCases.Any(t => t.RequirementId == r.Id))) Add(p, new() { Title = "Review: " + r.Text[..Math.Min(r.Text.Length, 80)], RequirementId = r.Id, ExecutionMode = "Manual", ExpectedResult = "Needs Oracle / Needs Review — verify source requirement", VerificationStatus = "Needs Oracle / Needs Review", TestType = "Static review", Steps = ["Review the cited source", "Record findings and evidence"] });
    }
    static void Add(Project p, TestCase t) { if (!p.TestCases.Any(x => x.RequirementId == t.RequirementId && x.Title == t.Title)) p.TestCases.Add(t); }
}
